args.command:
/bin/bash -lc "node --input-type=module <<'EOF'
const cases = [
  ['/', 200, '<title>Home Page</title>', '<h1>Home</h1>', 'href=\"/about\"'],
  ['/about', 200, '<title>About Us</title>', '<h1>About</h1>', 'href=\"/\"'],
  ['/contact', 404, '<h1 class=\"next-error-h1\"', '', ''],
]
for (const [path, expectedStatus, title, heading, link] of cases) {
  const response = await fetch("'`http://localhost:3000${path}`)
  const html = await response.text()
  if (response.status !== expectedStatus || !html.includes(title) || (heading && !html.includes(heading)) || (link && !html.includes(link)) || !html.includes('"'<html lang=\"en\">')) {
    throw new Error("'`Unexpected response for ${path}: ${response.status}`)
  }
  process.stdout.write(`${path}: ${response.status}, expected content present'"\\n"'`)
}
EOF'

